require '../config/database.php'; require '../includes/auth.php'; require_role('student');
$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT i.*,u.name AS reporter FROM items i JOIN users u ON u.id=i.user_id WHERE i.id=?");$s->execute([$id]);$item=$s->fetch();if(!$item){http_response_code(404);exit('Item not found.');}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$message=trim($_POST['message']??'');if($item['user_id']==$_SESSION['user']['id'])$error='You cannot claim your own report.';elseif($message==='')$error='Please explain why you believe this item belongs to you.';else{try{$s=$pdo->prepare('INSERT INTO claims(item_id,user_id,message) VALUES(?,?,?)');$s->execute([$id,$_SESSION['user']['id'],$message]);header('Location: my-claims.php?submitted=1');exit;}catch(PDOException $e){$error='You have already submitted a claim for this item.';}}}
$pageTitle='Item details';$assetPrefix='../';$homePrefix='../';require '../includes/header.php';
?>
<div class="detail-layout"><section class="panel"><span class="tag <?= e($item['type']) ?>"><?= e(ucfirst($item['type'])) ?></span><h1><?= e($item['title']) ?></h1><?php if($item['image']): ?><img class="detail-image" src="../uploads/<?= e($item['image']) ?>" alt="Item photo"><?php else: ?><div class="detail-placeholder">📦</div><?php endif; ?><h3>Description</h3><p><?= nl2br(e($item['description'])) ?></p><div class="detail-meta"><span>📍 <?= e($item['location']) ?></span><span>📅 <?= e($item['item_date']) ?></span><span>Category: <?= e($item['category']) ?></span></div></section>
<aside class="panel claim-panel"><h2>Is this yours?</h2><p class="muted">Submit a claim with details that help the admin verify ownership. Avoid sharing sensitive personal information.</p><?php if($error): ?><div class="alert"><?= e($error) ?></div><?php endif; ?><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label>Why is this item yours?<textarea name="message" rows="5" required placeholder="Mention identifying details only the owner would know..."></textarea></label><button class="btn btn-full">Submit claim</button></form><p class="tiny muted">Reported by <?= e($item['reporter']) ?></p></aside></div>
